function resumir(latencias) {
  // Relatório com NaN contamina tudo em silêncio.
  if (latencias.length === 0) return { media: 0, p50: 0, p95: 0 }

  // Cópia antes de ordenar: sort altera no lugar, e a lista é de quem chamou.
  const ordenadas = [...latencias].sort((a, b) => a - b)
  const n = ordenadas.length

  const percentil = (p) => ordenadas[Math.ceil((p / 100) * n) - 1]
  const soma = ordenadas.reduce((total, valor) => total + valor, 0)

  return {
    media: Math.round(soma / n),
    p50: Math.round(percentil(50)),
    p95: Math.round(percentil(95)),
  }
}

