function lerConfiguracao(env) {
  const faltando = ['DATABASE_URL', 'APP_SECRET'].filter((nome) => !env[nome])

  // Nomeia o que falta e para aí: valor de variável nunca entra na mensagem.
  if (faltando.length > 0) {
    throw new Error(`configuração ausente: ${faltando.join(', ')}`)
  }

  return {
    bancoUrl: env.DATABASE_URL,
    porta: Number(env.PORT ?? 3000),
    segredo: env.APP_SECRET,
  }
}
